        Seed("ex-stretch-03", "站姿股四头肌拉伸", "Standing Quad Stretch", "standing-quad-stretch", "legs", "Quads", "Hips,Mobility", "Bodyweight", "duration", true, "exercises/legs/standing-quad-stretch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "", ""),
        Seed("wg:seated-forward-fold-stretch", "坐姿前屈", "Seated Forward Fold", "seated-forward-fold-stretch", "legs", "Hamstrings", "Back,Calves,Mobility", "Bodyweight", "duration", true, "exercises/legs/seated-forward-fold-stretch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "", ""),
        Seed("wg:cross-body-shoulder-stretch", "交叉肩部拉伸", "Cross-Body Shoulder Stretch", "cross-body-shoulder-stretch", "shoulders", "Shoulders", "Upper Back,Mobility", "Bodyweight", "duration", true, "exercises/shoulders/cross-body-shoulder-stretch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "", ""),
        Seed("wg:wall-calf-stretch", "靠墙小腿拉伸", "Wall Calf Stretch", "wall-calf-stretch", "legs", "Calves", "Mobility", "Bodyweight", "duration", true, "exercises/legs/wall-calf-stretch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "", ""),
        Seed("wg:butterfly-stretch", "蝴蝶式拉伸", "Butterfly Stretch", "butterfly-stretch", "core", "Hips", "Groin,Mobility", "Bodyweight", "duration", true, "exercises/core/butterfly-stretch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "", ""),
        Seed("wg:kickboxing-aerobic", "搏击操", "Kickboxing Aerobic", "kickboxing-aerobic", "core", "Core", "Cardio,Shoulders", "Bodyweight", "duration", false, "exercises/core/kickboxing-aerobic/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "双脚开立与肩同宽，核心收紧，双手握拳护于下颌两侧\n出拳时转髋带动肩臂，直拳与摆拳交替，手臂不完全伸直锁肘\n配合出拳节奏做小幅度弹跳，前脚掌着地保持弹性\n每组 2-3 分钟，组间休息 30-60 秒，循环 4-6 组", "出拳时耸肩或手臂完全锁肘，容易拉伤肘关节\n只动手臂不转髋，核心发力不足且消耗大打折扣"),
        Seed("wg:aerobic-dance", "有氧舞蹈（尊巴）", "Aerobic Dance (Zumba)", "aerobic-dance", "legs", "Legs", "Cardio,Glutes", "Bodyweight", "duration", false, "exercises/legs/aerobic-dance/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "跟随音乐节拍做步伐组合，先慢速分解再逐渐提速\n手臂随躯干自然摆动，重心在双脚间流畅转移\n膝盖微屈缓冲，脚落地轻柔，避免跳跃动作落地过重\n连续 20-30 分钟，心率维持在最大心率的 60%-75%", "动作幅度过大导致重心失控，注意脚下支撑面\n全程憋气或只顾模仿动作忽略呼吸节奏"),
        Seed("wg:step-aerobics", "踏板操", "Step Aerobics", "step-aerobics", "legs", "Legs", "Cardio,Glutes", "Step", "duration", false, "exercises/legs/step-aerobics/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "调节踏板高度（初学 10-15cm），全脚掌踩实板面再发力\n上板时脚跟过渡到前掌，下板有序回落，配合摆臂\n保持节奏稳定不赶拍，每 8 拍换一次领先脚\n每次 15-25 分钟，板高与速度按体能递增", "只踩板面一半，落脚不稳容易崴脚\n下板时脚跟重重着地，膝关节冲击过大"),
        Seed("wg:trampoline-fitness", "健身蹦床", "Fitness Trampoline", "trampoline-fitness", "legs", "Legs", "Cardio,Core", "Cardio", "duration", false, "exercises/legs/trampoline-fitness/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "站在蹦床中央，双脚与髋同宽，膝盖微屈找弹性\n从轻微弹跳开始，逐渐加入开合跳、高抬腿等动作\n落点始终控制在网面中心，靠核心稳定躯干\n每次 15-20 分钟，关节压力小但能量消耗高", "落点偏离网心，弹跳失衡容易扭伤脚踝\n膝盖完全伸直落地，失去缓冲并冲击腰椎"),
        Seed("wg:versa-climber", "攀爬机", "Versa Climber", "versa-climber", "back", "Back", "Cardio,Legs", "Cardio", "duration", false, "exercises/back/versa-climber/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "双手握住活动把手，双脚踩踏板，四肢交替上下攀爬\n躯干直立微前倾，靠腿部主动蹬伸发力，手臂辅助\n按固定节奏连续攀爬，呼吸均匀不憋气\n初学者从 5-10 分钟开始，逐步延长到 20 分钟", "手臂代偿过多把体重压在肩上，很快力竭\n踏板蹬不到底动作幅度过小，训练效果打折"),
        Seed("wg:roller-skating", "轮滑", "Roller Skating", "roller-skating", "legs", "Legs", "Cardio,Glutes", "Cardio", "duration", false, "exercises/legs/roller-skating/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "穿戴头盔与护具，双脚呈 V 字站立找平衡再起步\n脚跟向侧前方蹬出，重心压低前倾，膝踝协同缓冲\n转弯时身体向弯道内侧倾斜，外侧脚持续蹬地\n新手先在平整慢速路段练习刹车与停止再上速度", "身体后仰重心偏后，向前摔倒风险最大\n不戴护具上坡或高速滑行，超出现阶段能力"),
        Seed("wg:tennis", "网球（单打）", "Tennis (Singles)", "tennis", "legs", "Legs", "Cardio,Shoulders", "Cardio", "duration", false, "exercises/legs/tennis/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "采用底线上手发球开始每一分，发球后快速回位\n正反手击球时转肩引拍，击球点保持在身体侧前方\n每次击球后回到中场准备姿势，用小碎步调整站位\n单打覆盖面积大，注意回合间隙的呼吸与放松", "只用手臂挥拍不转体，肩肘易受伤且球速不足\n跑动中伸腿够球不移动脚步，踝膝受伤风险高"),
        Seed("wg:volleyball", "排球", "Volleyball", "volleyball", "legs", "Legs", "Cardio,Shoulders", "Cardio", "duration", false, "exercises/legs/volleyball/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "准备姿势：屈膝降重心，双脚开立比肩略宽\n移动用滑步或交叉步，先到位再出手接球\n传球与垫球时手臂与肩形成稳定平面，靠下肢发力\n跳跃扣球起跳前充分制动，落地双膝弯曲缓冲", "落地单脚或直膝着地，踝膝损伤高发动作\n只用手臂发力垫球，失去下肢缓冲且控制不稳"),
        Seed("wg:basketball", "篮球", "Basketball", "basketball", "legs", "Legs", "Cardio,Core", "Cardio", "duration", false, "exercises/legs/basketball/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "重心放低，屈膝降重心，运球高度不超过腰部\n变向时用身体护球，抬头观察场上形势\n投篮手肘内收，手腕下压完成跟随动作\n传接球双手到位，接球瞬间形成三威胁姿态", "运球时低头看球，丢掉场上视野\n投篮只用手臂不蹬地，远距离命中率低"),
        Seed("wg:badminton", "羽毛球", "Badminton", "badminton", "legs", "Legs", "Cardio,Shoulders", "Cardio", "duration", false, "exercises/legs/badminton/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "握拍放松，掌心留空隙，发力瞬间才握紧\n高远球侧身架拍，转体鞭打，击球点在头前上方\n步伐交叉步与并步结合，每拍结束先回中\n杀球时后脚蹬地转髋，力量从下往上传导", "击球点落后于身体，只能被动过渡\n全程紧握拍柄，前臂易疲劳且爆发力差"),
        Seed("wg:soccer", "足球", "Soccer", "soccer", "legs", "Legs", "Cardio,Core", "Cardio", "duration", false, "exercises/legs/soccer/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "带球用脚内外侧交替触球，球距控制在一步内\n传球脚踝锁定，用脚弓推传地面球\n跑位接应斜向移动，给持球人留出传球线路\n射门支撑脚指向目标，击球瞬间收腹压住皮球", "带球步子过大球被断，触球力度忽轻忽重\n射门时身体后仰，皮球打高飞出横梁"),
        Seed("wg:table-tennis", "乒乓球", "Table Tennis", "table-tennis", "legs", "Legs", "Cardio,Arms", "Cardio", "duration", false, "exercises/legs/table-tennis/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "站位近台两脚开立，膝盖微屈重心前倾\n反手拨球以肘为轴小幅快挥，正手攻转腰带臂\n击球上升期触球，以摩擦为主保证弧线过网\n每分间隙迅速回位，小碎步预判来球", "站位离台过远只能伸臂够球，失去近台速度优势\n只打不摩擦，回球弧线低平失误率高"),
        Seed("wg:fencing", "击剑", "Fencing", "fencing", "legs", "Legs", "Cardio,Core", "Cardio", "duration", false, "exercises/legs/fencing/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "实战姿势双脚呈直角开立，持剑臂屈肘剑尖对准对手\n弓步进攻前脚出、后脚蹬，剑与腿同时到位\n防守以剑尖画小弧格挡，格挡后立即还击\n用节奏与真假动作结合调动对手重心", "剑尖下垂露出有效部位，先被对手攻击\n弓步前腿超过脚尖，回收慢容易失分"),
        Seed("wg:heavy-bag-boxing", "拳击沙袋", "Heavy Bag Boxing", "heavy-bag-boxing", "arms", "Arms", "Cardio,Shoulders", "Cardio", "duration", false, "exercises/arms/heavy-bag-boxing/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "以摇臂步法围绕沙袋移动，出拳时转髋送肩\n组合拳直拳开路摆拳收尾，节奏有快有慢\n出拳后迅速回到防御姿态，不贴死沙袋\n每轮 2-3 分钟，轮间充分甩臂放松", "出拳时手腕不绷直，击打瞬间容易挫腕\n只顾发力连续猛打，呼吸混乱迅速脱力"),
        Seed("wg:rock-climbing", "攀岩", "Rock Climbing", "rock-climbing", "back", "Back", "Cardio,Forearms", "Bodyweight", "duration", false, "exercises/back/rock-climbing/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "三点固定原则，移动一手一脚前先稳住重心\n多用腿部蹬伸上移，手臂只做锁定不拉引\n重心贴墙，臀部下沉减少手臂负担\n训练后拉伸前臂与肩背，防止肘部劳损", "全程用手臂拉身体，小臂很快力竭\n重心远离墙面，指尖与肘部承压过大"),
        Seed("wg:alpine-skiing", "双板滑雪", "Alpine Skiing", "alpine-skiing", "legs", "Legs", "Cardio,Core", "Cardio", "duration", false, "exercises/legs/alpine-skiing/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "基本站姿踝膝髋微屈，重心压在山上脚\n转弯靠山下脚内刃发力，膝盖带动雪板立刃\n雪杖点在转弯方向前方，配合重心移动\n控速先练犁式，再进阶平行式转弯", "身体后坐重心落后，转弯失控越滑越快\n面朝坡下低头看脚下，肩胛紧张动作变形"),
        Seed("wg:kayaking", "皮划艇", "Kayaking", "kayaking", "back", "Back", "Cardio,Shoulders", "Cardio", "duration", false, "exercises/back/kayaking/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "坐姿脊柱直立，双脚踩踏板膝盖微屈\n前划以转体带动桨叶，入桨沿船舷贴水\n转向用扫桨，桨叶画大弧推水\n激流段先看线路再下桨，桨始终在水里借力", "只用胳膊划桨不转体，肩膀很快疲劳\n重心后仰船头翘起，直线上跑偏"),
        Seed("wg:stepper", "踏步机", "Stepper", "stepper", "legs", "Legs", "Cardio,Glutes", "Cardio", "duration", false, "exercises/legs/stepper/frame-1.png", "{\"creator\": \"Seedream (Z.AI)\", \"creatorUrl\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"source\": {\"name\": \"Seedream\", \"url\": \"\", \"license\": \"AI-generated\", \"licenseUrl\": \"\", \"changes\": \"AI 生成单色剪影：裁边去水印，512x512 透明底 PNG 单帧静态\"}}", "全脚掌踩实踏板，膝盖与脚尖同向不内扣\n身体略前倾，握住扶手但不把体重压上去\n踏步节奏均匀，阻力由腿力控制不自由下坠\n每次 15-20 分钟，中途保持呼吸平稳", "踩踏半脚掌悬空，落脚不稳易崴脚\n把体重全压在扶手上，训练强度大打折扣"),
